public sealed interface OrderEvent permits OrderConfirmed, OrderShipped {}
public record OrderConfirmed(String orderId, Instant occurredOn) implements OrderEvent {}

void dispatch(OrderEvent e) {
    switch (e) {
        case OrderConfirmed c -> projections.apply(c);
        case OrderShipped s   -> shipping.notify(s);
    }   // no default: the compiler checks the sealed hierarchy
}
